// ───────── OSM MERGE ─────────

import { OSM_RESTAURANTS, type OsmRestaurant } from "./restaurants-osm";

const OSM_SRC = {
  label: "OpenStreetMap — © OSM contributors",
  url: "https://www.openstreetmap.org/copyright",
};

function normName(s: string): string {
  return s
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/[^a-z0-9]+/g, "");
}

function osmToRestaurant(o: OsmRestaurant): Restaurant {
  return {
    id: o.id,
    name: o.name,
    cuisine: o.cuisine,
    category: o.category,
    area: o.area,
    city: o.city,
    address: o.address,
    highlights: [],
    sources: [
      {
        ...OSM_SRC,
        url: `https://www.openstreetmap.org/${o.osmId}`,
      },
    ],
    source: "osm",
    lat: o.lat,
    lng: o.lng,
    osmId: o.osmId,
    phone: o.phone,
    website: o.website,
  };
}

/** Wraps a curated entry with derived `city` and the `source` discriminator. */
function curatedToRestaurant(r: Omit<Restaurant, "source" | "city">): Restaurant {
  return { ...r, city: deriveCityFromArea(r.area), source: "curated" };
}

// Dedup fingerprint: name + city. This drops OSM duplicates of curated
// venues in the same district while preserving distinct chain branches
// (e.g. Pizza Marzano at KK Mall vs at Plaza Indonesia stay separate
// because they're in different DKI sub-regions). For OSM-internal dedup,
// fetch-osm.ts already collapses entries sharing name + ~111m coords.
function fingerprint(name: string, city: string): string {
  return `${normName(name)}|${city.toLowerCase()}`;
}

const curatedFingerprints = new Set(
  CURATED.map((c) => fingerprint(c.name, deriveCityFromArea(c.area)))
);

const ALL_OSM = OSM_RESTAURANTS.filter(
  (o) => !curatedFingerprints.has(fingerprint(o.name, o.city))
);

// DKI-only: drop curated outliers in Bodetabek (e.g. Ciputat/Tangerang)
// and any OSM entries flagged as Tangerang/Bekasi/Depok/Bogor.
export const RESTAURANTS: Restaurant[] = [
  ...CURATED.map(curatedToRestaurant).filter((r) => DKI_CITIES.has(r.city)),
  ...ALL_OSM.map(osmToRestaurant).filter((r) => DKI_CITIES.has(r.city)),
];

// ───────── HELPERS ─────────

export function googleMapsUrl(r: Restaurant): string {
  if (r.lat != null && r.lng != null) {
    return `https://www.google.com/maps/search/?api=1&query=${r.lat},${r.lng}`;
  }
  const q = [r.name, r.address ?? r.area, "Jakarta"]
    .filter(Boolean)
    .join(", ");
  return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(q)}`;
}

/**
 * Returns a Google Maps embed URL. Uses exact lat/lng when available
 * (OSM entries) — otherwise falls back to a text query. No API key.
 */
export function mapsEmbedUrl(r: Restaurant): string {
  if (r.lat != null && r.lng != null) {
    return `https://www.google.com/maps?q=${r.lat},${r.lng}&hl=en&z=17&output=embed`;
  }
  const q = [r.name, r.address ?? r.area, "Jakarta"]
    .filter(Boolean)
    .join(", ");
  return `https://www.google.com/maps?q=${encodeURIComponent(q)}&hl=en&z=16&output=embed`;
}

export function getCuisineList(): string[] {
  return Array.from(new Set(RESTAURANTS.map((r) => r.cuisine))).sort();
}

export function getAreaList(): string[] {
  return Array.from(new Set(RESTAURANTS.map((r) => r.area))).sort();
}

/** Cities present in the dataset, ordered DKI-first then alphabetical. */
export function getCityList(): string[] {
  const present = new Set(RESTAURANTS.map((r) => r.city));
  const ordered: string[] = [];
  for (const c of CITY_ORDER) if (present.has(c)) ordered.push(c);
  for (const c of [...present].sort()) {
    if (!ordered.includes(c)) ordered.push(c);
  }
  return ordered;
}
